seen=set()
out={"version":1,"causes":{k:{"en":v[0],"ar":v[1]} for k,v in causes.items()},"steps":{k:{"en":v[0],"ar":v[1]} for k,v in steps.items()},"codes":[]}
for c in codes:
    code,sysn,sev,en,ar,cs,st=c
    assert code not in seen, code; seen.add(code)
    for k in cs: assert k in causes,(code,k)
    for k in st: assert k in steps,(code,k)
    out["codes"].append({"code":code,"system":sysn,"severity":sev,"en":en,"ar":ar,"causes":cs,"steps":st})
json.dump(out,open(sys.argv[1],'w'),ensure_ascii=False,indent=1)
print(len(codes),"codes",len(causes),"causes",len(steps),"steps")
